import Foundation
import WorkspaceProtocol

/// Request builders and response readers for the `codex app-server` v2 protocol, hand-written from
/// the JSON schema generated by the pinned binary (`codex app-server generate-json-schema`,
/// codex-cli 0.166.0, 2026-10-30). Only the fields the app reads are typed; everything else stays
/// `JSONValue` so a newer server cannot break decoding.
public enum CodexProtocol {
  public static let clientName = "agent_workspace"
  public static let clientTitle = "Personal Agent Workspace"

  // MARK: - Client requests

  public static func initializeParams(version: String) -> JSONValue {
    [
      "clientInfo": [
        "name": .string(clientName), "title": .string(clientTitle), "version": .string(version),
      ],
      "capabilities": ["experimentalApi": false, "optOutNotificationMethods": []],
    ]
  }

  public static func accountReadParams() -> JSONValue { ["refreshToken": false] }

  public static func loginStartParams() -> JSONValue { ["type": "chatgpt"] }

  /// Per-thread policy override (generated-schema strings: `AskForApproval` is `untrusted |
  /// on-request | never`, `SandboxMode` is `read-only | workspace-write | danger-full-access`).
  /// The app never passes one (D-012); the live approval test asks for a stricter policy than the
  /// owner's configuration so a real approval request can be exercised.
  public struct ThreadPolicy: Sendable, Equatable {
    public var approvalPolicy: String
    public var sandbox: String
    public init(approvalPolicy: String, sandbox: String) {
      self.approvalPolicy = approvalPolicy
      self.sandbox = sandbox
    }
  }

  public static func threadStartParams(cwd: String?, policy: ThreadPolicy? = nil) -> JSONValue {
    var params: [String: JSONValue] = ["serviceName": .string(clientName)]
    if let cwd { params["cwd"] = .string(cwd) }
    if let policy {
      params["approvalPolicy"] = .string(policy.approvalPolicy)
      params["sandbox"] = .string(policy.sandbox)
    }
    return .object(params)
  }

  public static func threadResumeParams(threadId: String, cwd: String?) -> JSONValue {
    var params: [String: JSONValue] = ["threadId": .string(threadId), "excludeTurns": true]
    if let cwd { params["cwd"] = .string(cwd) }
    return .object(params)
  }

  public static func threadReadParams(threadId: String) -> JSONValue {
    ["threadId": .string(threadId), "includeTurns": false]
  }

  public static func turnsListParams(threadId: String, limit: Int = 200) -> JSONValue {
    [
      "threadId": .string(threadId), "itemsView": "full", "sortDirection": "asc",
      "limit": .number(Double(limit)),
    ]
  }

  public static func turnStartParams(threadId: String, text: String, cwd: String?) -> JSONValue {
    var params: [String: JSONValue] = [
      "threadId": .string(threadId), "input": [["type": "text", "text": .string(text)]],
    ]
    if let cwd { params["cwd"] = .string(cwd) }
    return .object(params)
  }

  public static func turnInterruptParams(threadId: String, turnId: String) -> JSONValue {
    ["threadId": .string(threadId), "turnId": .string(turnId)]
  }

  // MARK: - Server requests

  /// Server-to-client request methods and the runtime request kind each one maps to.
  public enum ServerRequestMethod: String, Sendable, CaseIterable {
    case commandApproval = "item/commandExecution/requestApproval"
    case fileChangeApproval = "item/fileChange/requestApproval"
    case userInput = "item/tool/requestUserInput"
    case elicitation = "mcpServer/elicitation/request"
    case permissions = "item/permissions/requestApproval"
    case toolCall = "item/tool/call"
    case authTokensRefresh = "account/chatgptAuthTokens/refresh"
    case attestation = "attestation/generate"
    case legacyExecApproval = "execCommandApproval"
    case legacyPatchApproval = "applyPatchApproval"

    public var kind: RuntimeRequestKind {
      switch self {
      case .commandApproval, .legacyExecApproval: return .commandApproval
      case .fileChangeApproval, .legacyPatchApproval: return .fileChangeApproval
      case .userInput: return .userQuestion
      case .elicitation: return .elicitation
      case .permissions: return .toolPermission
      case .toolCall, .authTokensRefresh, .attestation: return .unknown
      }
    }

    /// Whether the app can present and answer this request with a user decision.
    public var answerable: Bool {
      switch self {
      case .commandApproval, .fileChangeApproval, .userInput, .legacyExecApproval, .legacyPatchApproval:
        return true
      case .elicitation, .permissions, .toolCall, .authTokensRefresh, .attestation: return false
      }
    }

    var isLegacy: Bool { self == .legacyExecApproval || self == .legacyPatchApproval }
  }

  public static func requestKind(method: String) -> RuntimeRequestKind {
    ServerRequestMethod(rawValue: method)?.kind ?? .unknown
  }

  /// Keys copied into the safe display payload for each request kind. Nothing else leaves the adapter.
  static func safeRequestPayload(method: ServerRequestMethod, params: JSONValue) -> JSONValue {
    let keys: [String]
    switch method {
    case .commandApproval: keys = ["itemId", "command", "cwd", "reason", "kind", "networkApprovalContext"]
    case .fileChangeApproval: keys = ["itemId", "reason", "grantRoot"]
    case .userInput: keys = ["itemId", "questions", "isBlocking"]
    case .elicitation: keys = ["message", "mode"]
    case .permissions: keys = ["itemId", "cwd", "reason", "permissions"]
    case .toolCall: keys = ["tool", "namespace", "callId"]
    case .authTokensRefresh, .attestation: keys = []
    case .legacyExecApproval: keys = ["callId", "command", "cwd", "reason"]
    case .legacyPatchApproval: keys = ["callId", "fileChanges", "grantRoot", "reason"]
    }
    var out: [String: JSONValue] = [:]
    for key in keys {
      if let value = params[key], !value.isNull { out[key] = value }
    }
    return .object(out)
  }

  /// The result body for a user decision on an approval request.
  public static func approvalResponse(_ decision: RuntimeDecision, legacy: Bool) -> JSONValue {
    if legacy {
      switch decision {
      case .allowOnce: return ["decision": "approved"]
      case .allowAlways: return ["decision": "approved_for_session"]
      case .deny: return ["decision": ["denied": ["rejection": "Declined in Personal Agent Workspace."]]]
      }
    }
    switch decision {
    case .allowOnce: return ["decision": "accept"]
    case .allowAlways: return ["decision": "acceptForSession"]
    case .deny: return ["decision": "decline"]
    }
  }

  public static func userInputResponse(_ answers: [String: [String]]) -> JSONValue {
    .object([
      "answers": .object(
        answers.mapValues { values in .object(["answers": .array(values.map(JSONValue.string))]) })
    ])
  }

  /// A valid explicit decline for a request the app cannot present, or nil when the protocol offers
  /// no decline body (the adapter then answers with a JSON-RPC error).
  public static func declineResponse(method: ServerRequestMethod) -> JSONValue? {
    switch method {
    case .commandApproval, .fileChangeApproval: return ["decision": "decline"]
    case .legacyExecApproval, .legacyPatchApproval:
      return ["decision": ["denied": ["rejection": "Declined in Personal Agent Workspace."]]]
    case .userInput: return ["answers": [:]]
    case .elicitation: return ["action": "decline"]
    case .permissions: return ["permissions": [:], "scope": "turn"]
    case .toolCall:
      return [
        "success": false,
        "contentItems": [
          ["type": "inputText", "text": "Dynamic tools are not supported by Personal Agent Workspace."]
        ],
      ]
    case .authTokensRefresh, .attestation: return nil
    }
  }

  // MARK: - Errors

  /// Map Codex's `codexErrorInfo` to the app's stable error codes.
  public static func errorCode(codexErrorInfo: JSONValue?) -> ErrorCode {
    let name: String?
    if let text = codexErrorInfo?.stringValue {
      name = text
    } else if let object = codexErrorInfo?.objectValue {
      name = object.keys.first
    } else {
      name = nil
    }
    switch name {
    case "usageLimitExceeded", "rateLimitExceeded", "sessionBudgetExceeded": return .allowanceExceeded
    case "unauthorized": return .authRequired
    case "httpConnectionFailed", "responseStreamConnectionFailed", "responseStreamDisconnected",
      "serverOverloaded":
      return .endpointUnavailable
    default: return .internalError
    }
  }
}

/// Reduced account status. Only type, email, and plan leave the adapter; tokens never appear.
public struct CodexAccount: Sendable, Equatable, Codable {
  public var type: String
  public var email: String?
  public var planType: String?

  public init(type: String, email: String? = nil, planType: String? = nil) {
    self.type = type
    self.email = email
    self.planType = planType
  }

  /// Parse an `account/read` result. Returns nil when `account` is null (signed out).
  public init?(accountReadResult result: JSONValue) {
    guard let account = result["account"], let type = account["type"]?.stringValue else { return nil }
    self.type = type
    self.email = account["email"]?.stringValue
    self.planType = account["planType"]?.stringValue
  }

  /// Native scope used to namespace thread ids: the signed-in email, else the auth type.
  public var nativeScope: String { email ?? type }
}
